using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories =
        [
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🥨" },
            new() { Name = "Beverages", Description = "Refreshing drinks and smoothies", Icon = "🥤" },
        ];

        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Ingredients = "2 cups flour\n3 tsp baking powder\n1 tsp salt\n2 tbsp sugar\n2 eggs\n1½ cups milk\n¼ cup melted butter",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Make a well and add eggs, milk, and butter.\n3. Stir until smooth.\n4. Pour ¼ cup batter onto hot griddle.\n5. Flip when bubbles form, cook until golden.",
                AverageRating = 4.5, RatingCount = 12
            },
            new()
            {
                Id = 2, Title = "Caesar Salad", Category = "Lunch",
                Ingredients = "1 head romaine lettuce\n½ cup croutons\n¼ cup parmesan cheese\nCaesar dressing\nBlack pepper",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and parmesan.\n4. Season with black pepper.\n5. Serve immediately.",
                AverageRating = 4.2, RatingCount = 8
            },
            new()
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 cloves garlic\n400g crushed tomatoes\n2 tbsp tomato paste\nSalt, pepper, oregano",
                Steps = "1. Cook spaghetti according to package.\n2. Brown beef in a pan, drain fat.\n3. Sauté onion and garlic.\n4. Add tomatoes, paste, and seasonings.\n5. Simmer 20 minutes.\n6. Serve sauce over pasta.",
                AverageRating = 4.8, RatingCount = 24
            },
            new()
            {
                Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "2¼ cups flour\n1 tsp baking soda\n1 cup butter, softened\n¾ cup sugar\n¾ cup brown sugar\n2 eggs\n2 cups chocolate chips",
                Steps = "1. Preheat oven to 375°F.\n2. Cream butter and sugars.\n3. Beat in eggs.\n4. Mix in flour and baking soda.\n5. Stir in chocolate chips.\n6. Drop spoonfuls onto baking sheet.\n7. Bake 9-11 minutes.",
                AverageRating = 4.9, RatingCount = 31
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Snacks",
                Ingredients = "3 avocados\n1 lime, juiced\n1 tsp salt\n½ cup onion, diced\n3 tbsp cilantro\n2 tomatoes, diced\n1 tsp garlic",
                Steps = "1. Mash avocados in a bowl.\n2. Stir in lime juice and salt.\n3. Mix in onion, cilantro, tomatoes, and garlic.\n4. Refrigerate 1 hour for best flavor.\n5. Serve with tortilla chips.",
                AverageRating = 4.6, RatingCount = 15
            },
            new()
            {
                Id = 6, Title = "Berry Smoothie", Category = "Beverages",
                Ingredients = "1 cup mixed berries\n1 banana\n1 cup yogurt\n½ cup milk\n1 tbsp honey\nIce cubes",
                Steps = "1. Add all ingredients to blender.\n2. Blend on high for 30 seconds.\n3. Pour into glass and serve immediately.",
                AverageRating = 4.3, RatingCount = 9
            },
        ];
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        };
        _recipes.Add(recipe);
    }

    public void RateRecipe(int recipeId, int rating)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null) return;

        var totalRating = recipe.AverageRating * recipe.RatingCount;
        recipe.RatingCount++;
        recipe.AverageRating = (totalRating + rating) / recipe.RatingCount;
    }
}

