@page "/"

<PageTitle>Recipe Community</PageTitle>

<div class="container mt-4">
    <div class="text-center mb-5">
        <h1 class="display-4">🍳 Recipe Community</h1>
        <p class="lead text-muted">Discover, share, and rate delicious recipes from our community</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in Categories)
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body text-center">
                        <div class="display-3 mb-3">@category.Icon</div>
                        <h5 class="card-title">@category.Name</h5>
                        <p class="card-text text-muted">@category.Description</p>
                        <a href="/category/@category.Name.ToLower()" class="btn btn-outline-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-4">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.RecipeCategory> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category yet. <a href="/submit">Be the first to submit one!</a></div>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <div class="mb-2">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span class="@(i <= Math.Round(recipe.AverageRating) ? "text-warning" : "text-muted")">★</span>
                                }
                                <small class="text-muted ms-1">(@recipe.AverageRating.ToString("F1")) · @recipe.RatingCount ratings</small>
                            </div>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeCommunity.Models.Recipe> Recipes { get; set; } = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <h1 class="card-title mb-3">@Recipe.Title</h1>
                <span class="badge bg-secondary mb-3">@Recipe.Category</span>

                <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating"
                            RatingCount="Recipe.RatingCount" OnRate="HandleRate" />

                <hr />

                <h4>🥘 Ingredients</h4>
                <div class="mb-4 ps-3" style="white-space: pre-line;">@Recipe.Ingredients</div>

                <h4>📋 Steps</h4>
                <div class="ps-3" style="white-space: pre-line;">@Recipe.Steps</div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRate(int rating)
    {
        RecipeService.RateRecipe(Id, rating);
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer

<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var starValue = i;
        <span class="star-rating @(i <= _hoverRating ? "text-warning" : (i <= Math.Round(CurrentRating) ? "text-warning" : "text-muted"))"
              style="cursor: pointer; font-size: 1.5rem;"
              @onmouseover="() => _hoverRating = starValue"
              @onmouseout="() => _hoverRating = 0"
              @onclick="() => Rate(starValue)">★</span>
    }
    <span class="ms-2 text-muted">
        @CurrentRating.ToString("F1") avg · @RatingCount ratings
        @if (_userRating > 0)
        {
            <span class="text-success ms-2">✓ You rated @_userRating star@(_userRating > 1 ? "s" : "")</span>
        }
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRate { get; set; }

    private int _hoverRating;
    private int _userRating;

    private async Task Rate(int rating)
    {
        _userRating = rating;
        await OnRate.InvokeAsync(rating);
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@_model.Title</strong>" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="title" class="form-label">Recipe Title</label>
                        <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
                        <ValidationMessage For="() => _model.Title" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="category" class="form-label">Category</label>
                        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                            <option value="">-- Select a category --</option>
                            @foreach (var cat in _categories)
                            {
                                <option value="@cat.Name">@cat.Icon @cat.Name</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.Category" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="ingredients" class="form-label">Ingredients</label>
                        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients"
                                       placeholder="List each ingredient on a new line..." />
                        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="steps" class="form-label">Steps</label>
                        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                                       placeholder="Describe each step..." />
                        <ValidationMessage For="() => _model.Steps" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.RecipeSubmission _model = new();
    private List<RecipeCommunity.Models.RecipeCategory> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

