toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<div class="container mt-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit a Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>🎉 Recipe submitted successfully!</h4>
            <p>Your recipe "<strong>@_model.Title</strong>" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <div class="card shadow-sm">
            <div class="card-body">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="title" class="form-label">Recipe Title</label>
                        <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
                        <ValidationMessage For="() => _model.Title" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="category" class="form-label">Category</label>
                        <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                            <option value="">-- Select a category --</option>
                            @foreach (var cat in _categories)
                            {
                                <option value="@cat.Name">@cat.Icon @cat.Name</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.Category" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="ingredients" class="form-label">Ingredients</label>
                        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients"
                                       placeholder="List each ingredient on a new line..." />
                        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="steps" class="form-label">Steps</label>
                        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                                       placeholder="Describe each step..." />
                        <ValidationMessage For="() => _model.Steps" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeCommunity.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeCommunity.Models.RecipeSubmission _model = new();
    private List<RecipeCommunity.Models.RecipeCategory> _categories = [];
    private bool _submitted;

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model);
        _submitted = true;
    }
}

